import {
  Progress as ProgressPrimitive,
  useProgress,
  useProgressContext,
} from '@ark-ui/react/progress';
import { clsx } from 'clsx';
import type { ComponentProps, ComponentRef } from 'react';
import { forwardRef } from 'react';
import styles from './ProgressLinear.module.css';

const ProgressLinear = forwardRef<
  ComponentRef<typeof ProgressPrimitive.Root>,
  ComponentProps<typeof ProgressPrimitive.Root>
>(function ProgressLinear({ className, ...props }, ref) {
  return (
    <ProgressPrimitive.Root
      ref={ref}
      className={clsx(styles.root, className)}
      {...props}
      data-slot="progress-linear-root"
    />
  );
});

const ProgressLinearRootProvider = forwardRef<
  ComponentRef<typeof ProgressPrimitive.RootProvider>,
  ComponentProps<typeof ProgressPrimitive.RootProvider>
>(function ProgressLinearRootProvider({ className, ...props }, ref) {
  return (
    <ProgressPrimitive.RootProvider
      ref={ref}
      className={clsx(styles.root, className)}
      {...props}
      data-slot="progress-linear-root-provider"
    />
  );
});

const ProgressLinearLabel = forwardRef<
  ComponentRef<typeof ProgressPrimitive.Label>,
  ComponentProps<typeof ProgressPrimitive.Label>
>(function ProgressLinearLabel({ className, ...props }, ref) {
  return (
    <ProgressPrimitive.Label
      ref={ref}
      className={clsx(styles.label, className)}
      {...props}
      data-slot="progress-linear-label"
    />
  );
});

const ProgressLinearValueText = forwardRef<
  ComponentRef<typeof ProgressPrimitive.ValueText>,
  ComponentProps<typeof ProgressPrimitive.ValueText>
>(function ProgressLinearValueText({ className, ...props }, ref) {
  return (
    <ProgressPrimitive.ValueText
      ref={ref}
      className={clsx(styles.valueText, className)}
      {...props}
      data-slot="progress-linear-value-text"
    />
  );
});

const ProgressLinearTrack = forwardRef<
  ComponentRef<typeof ProgressPrimitive.Track>,
  ComponentProps<typeof ProgressPrimitive.Track>
>(function ProgressLinearTrack({ className, ...props }, ref) {
  return (
    <ProgressPrimitive.Track
      ref={ref}
      className={clsx(styles.track, className)}
      {...props}
      data-slot="progress-linear-track"
    />
  );
});

const ProgressLinearRange = forwardRef<
  ComponentRef<typeof ProgressPrimitive.Range>,
  ComponentProps<typeof ProgressPrimitive.Range>
>(function ProgressLinearRange({ className, ...props }, ref) {
  return (
    <ProgressPrimitive.Range
      ref={ref}
      className={clsx(styles.range, className)}
      {...props}
      data-slot="progress-linear-range"
    />
  );
});

const ProgressLinearView = forwardRef<
  ComponentRef<typeof ProgressPrimitive.View>,
  ComponentProps<typeof ProgressPrimitive.View>
>(function ProgressLinearView(props, ref) {
  return <ProgressPrimitive.View ref={ref} {...props} data-slot="progress-linear-view" />;
});

const ProgressLinearContext = ProgressPrimitive.Context;

export {
  ProgressLinear,
  ProgressLinearContext,
  ProgressLinearLabel,
  ProgressLinearRange,
  ProgressLinearRootProvider,
  ProgressLinearTrack,
  ProgressLinearValueText,
  ProgressLinearView,
  useProgress,
  useProgressContext,
};
export type {
  ProgressContextProps,
  ProgressLabelProps,
  ProgressRangeProps,
  ProgressRootProps,
  ProgressRootProviderProps,
  ProgressTrackProps,
  ProgressValueChangeDetails,
  ProgressValueTextProps,
  ProgressValueTranslationDetails,
  ProgressViewProps,
  UseProgressContext,
  UseProgressProps,
  UseProgressReturn,
} from '@ark-ui/react/progress';

@layer moduix.components {
  .root {
    display: grid;
    grid-template-columns: minmax(0, 1fr) auto;
    gap: var(--moduix-spacing-2);
    width: 100%;

    &[data-orientation='vertical'] {
      grid-template-rows: auto minmax(0, 1fr);
      width: max-content;
      height: 12rem;
    }
  }

  .label,
  .valueText {
    font-size: var(--moduix-text-sm);
    line-height: var(--moduix-line-height-text-sm);
    overflow-wrap: anywhere;
  }

  .valueText {
    justify-self: end;
    text-align: end;
  }

  .track {
    grid-column: 1 / -1;
    overflow: hidden;
    height: var(--moduix-progress-linear-track-size, var(--moduix-spacing-2));
    border-radius: var(--moduix-radius-full);
    background-color: var(--moduix-progress-linear-track-bg, var(--moduix-color-muted));
    box-shadow: inset 0 0 0 var(--moduix-border-width-sm) var(--moduix-color-border);

    &[data-orientation='vertical'] {
      display: flex;
      align-items: end;
      justify-self: center;
      width: var(--moduix-progress-linear-track-size, var(--moduix-spacing-2));
      height: 100%;
    }
  }

  .range {
    height: 100%;
    border-radius: inherit;
    background-color: var(--moduix-progress-linear-range-bg, var(--moduix-color-primary));
    transition:
      width var(--moduix-transition-default),
      height var(--moduix-transition-default);

    /* Ark leaves the range size unset while the value is unknown. */
    &[data-state='indeterminate'] {
      width: 35%;
      animation: global(moduix-progress-linear-indeterminate) 1.5s ease-in-out infinite;
    }

    &[data-orientation='vertical'] {
      width: 100%;
    }

    &[data-state='indeterminate'][data-orientation='vertical'] {
      height: 35%;
      animation: global(moduix-progress-linear-indeterminate-vertical) 1.5s ease-in-out infinite;
    }

    /* The RTL range starts at the right edge; mirroring it turns the sweep right-to-left. */
    &[data-state='indeterminate'][data-orientation='horizontal']:dir(rtl) {
      scale: -1 1;
    }

    @media (prefers-reduced-motion: reduce) {
      &[data-state='indeterminate'] {
        animation: none;
      }
    }
  }
}
